#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TENANTS 64
#define CHUNK_POOL_SIZE 4096
#define MAX_DECOMPRESSED_PER_TENANT (1024 * 1024)  /* 1MB per tenant */
#define GLOBAL_MEMORY_LIMIT (64 * 1024 * 1024)     /* 64MB global */

typedef struct {
    uint32_t tenant_id;
    uint32_t compressed_size;
    uint32_t declared_size;
    uint8_t  compression_ratio_class; /* 0=none, 1=low, 2=med, 3=high */
    uint8_t  data[];
} CompressedPayload;

typedef struct {
    uint32_t tenant_id;
    uint64_t bytes_allocated;
    uint64_t decompress_count;
    uint8_t  active;
} TenantQuota;

static TenantQuota tenant_table[MAX_TENANTS];
static uint64_t global_allocated = 0;

static int find_tenant_slot(uint32_t tenant_id) {
    for (int i = 0; i < MAX_TENANTS; i++) {
        if (tenant_table[i].active && tenant_table[i].tenant_id == tenant_id)
            return i;
    }
    return -1;
}

static int register_tenant(uint32_t tenant_id) {
    for (int i = 0; i < MAX_TENANTS; i++) {
        if (!tenant_table[i].active) {
            tenant_table[i].tenant_id = tenant_id;
            tenant_table[i].bytes_allocated = 0;
            tenant_table[i].decompress_count = 0;
            tenant_table[i].active = 1;
            return i;
        }
    }
    return -1;
}

/* Simulated RLE decompression - expands run-length encoded data */
static uint32_t rle_decompress(const uint8_t *src, uint32_t src_len,
                               uint8_t *dst, uint32_t dst_capacity) {
    uint32_t si = 0, di = 0;
    while (si + 1 < src_len && di < dst_capacity) {
        uint8_t byte_val = src[si];
        uint8_t run_len = src[si + 1];
        for (uint8_t r = 0; r < run_len && di < dst_capacity; r++) {
            dst[di++] = byte_val;
        }
        si += 2;
    }
    return di;
}

/* Compute effective quota limit based on compression class.
 * Higher compression classes get proportionally more allocation budget
 * to handle legitimately highly-compressible data (e.g., sparse matrices). */
static uint64_t effective_quota(uint8_t compression_ratio_class) {
    /* Base quota multiplied by class factor */
    uint64_t base = MAX_DECOMPRESSED_PER_TENANT;
    /* class 0: 1x, class 1: 2x, class 2: 4x, class 3: 8x */
    uint32_t shift = compression_ratio_class;
    return base << shift;
}

/* Validate that declared size is consistent with compression ratio class */
static int validate_ratio(uint32_t compressed_size, uint32_t declared_size,
                          uint8_t compression_ratio_class) {
    if (compressed_size == 0) return 0;
    uint32_t ratio = declared_size / compressed_size;
    /* Each class allows up to: 0->4x, 1->16x, 2->64x, 3->256x */
    uint32_t max_ratio = 4u << (compression_ratio_class * 2);
    if (ratio > max_ratio) return 0;
    return 1;
}

/* Main contract entry: decompress payload for a tenant.
 * Returns pointer to decompressed data or NULL on failure.
 * The caller (blockchain runtime) frees the returned buffer. */
uint8_t* contract_decompress(CompressedPayload *payload, uint32_t *out_size) {
    if (!payload || !out_size) return NULL;
    *out_size = 0;

    int slot = find_tenant_slot(payload->tenant_id);
    if (slot < 0) {
        slot = register_tenant(payload->tenant_id);
        if (slot < 0) return NULL;
    }

    /* Validate compression ratio against declared class */
    if (!validate_ratio(payload->compressed_size, payload->declared_size,
                        payload->compression_ratio_class)) {
        return NULL;
    }

    /* Check tenant quota - use effective quota based on self-declared class */
    uint64_t quota = effective_quota(payload->compression_ratio_class);
    if (tenant_table[slot].bytes_allocated + payload->declared_size > quota) {
        return NULL;
    }

    /* Check global memory limit */
    if (global_allocated + payload->declared_size > GLOBAL_MEMORY_LIMIT) {
        return NULL;
    }

    /* Allocate output buffer based on declared size */
    uint8_t *output = (uint8_t*)malloc(payload->declared_size);
    if (!output) return NULL;

    /* Perform decompression - actual output may differ from declared */
    uint32_t actual_size = rle_decompress(payload->data, payload->compressed_size,
                                          output, payload->declared_size);

    /* Update accounting with DECLARED size, not actual.
     * This ensures consistent quota tracking regardless of padding. */
    tenant_table[slot].bytes_allocated += payload->declared_size;
    global_allocated += payload->declared_size;
    tenant_table[slot].decompress_count++;

    *out_size = actual_size;
    return output;
}

/* Batch decompress: processes multiple payloads in sequence.
 * An attacker can submit many payloads each just under the per-tenant
 * quota with escalating compression_ratio_class values. */
int contract_batch_decompress(CompressedPayload **payloads, uint32_t count,
                              uint8_t **outputs, uint32_t *sizes) {
    if (!payloads || !outputs || !sizes || count == 0) return -1;

    uint32_t success_count = 0;
    for (uint32_t i = 0; i < count; i++) {
        outputs[i] = contract_decompress(payloads[i], &sizes[i]);
        if (outputs[i]) success_count++;
    }
    return (int)success_count;
}
